    "CREATE UNIQUE INDEX idx_learning_conference_current_revision\n                        ON learning_conference_revisions(learning_conference_id)\n                        WHERE status = 'completed'",
    "CREATE INDEX idx_learning_conference_revisions_number\n                        ON learning_conference_revisions(\n                            learning_conference_id,\n                            revision_number\n                        )",
